const container = document.querySelector("#bookmarkApp")
const list = document.getElementById("bookmarkList");
const bookmarkURL = document.getElementById("bookmarkInput");
const addBtn = document.getElementById("addBookmarkBtn");
const links = [];

const renderElements = (elements) => {
  list.innerHTML = "";
  elements.forEach((item) => {
    
  });
  list.querySelectorAll(".bookmarkItem").forEach((item) => {
    const deleteBtn = document.createElement("button");
    deleteBtn.classList.add("delete-btn");
    item.append(deleteBtn);
    deleteBtn.addEventListener("click", (e) => {
      e.target.parentElement.remove();
      links.splice(e.target.parentElement.dataset.id, 1);
    });
    deleteBtn.textContent = "x";
  });
}

addBtn.addEventListener("click", () => {
  links.push(bookmarkURL.value);
  console.log(links);
  renderElements(links);
});